"""Chapter 10: Radical Reactions (50 multiple choice + 50 free response)."""
from qb import *


def build(b):
    # ------------------------------------------------------------ 10.1 Radicals
    b.mc('10.1', 1, 'What is a radical?', 'A species with an unpaired electron', ['A species with a positive charge on carbon', 'A species with a lone pair and a negative charge', 'A species with an empty p orbital only'], 'Radicals have one unpaired electron and are usually highly reactive.')
    b.mc('10.1', 1, 'What kind of arrow shows the movement of a single electron?', 'A fishhook (half-headed) arrow', ['A full-headed curved arrow', 'An equilibrium arrow', 'A straight arrow'], 'A full arrow moves a pair of electrons.')
    b.mc('10.1', 2, 'Which radical is the most stable?', 'Tertiary', ['Secondary', 'Primary', 'Methyl'], 'Radical stability follows the same trend as carbocation stability.')
    b.mc('10.1', 2, 'Which radical is stabilised by resonance?', 'The allyl radical, CH₂=CH-CH₂•', ['The vinyl radical, CH₂=CH•', 'The methyl radical', 'The ethyl radical'], 'The unpaired electron of the allyl radical is delocalised over two carbons.', img=S('C=C[CH2]', radical=True))
    b.mc('10.1', 3, 'Rank these radicals from most stable to least stable: methyl, primary, secondary, allylic.', 'Allylic > secondary > primary > methyl', ['Secondary > allylic > primary > methyl', 'Methyl > primary > secondary > allylic', 'Allylic > methyl > primary > secondary'], 'Resonance stabilisation outweighs substitution.')
    b.mc('10.1', 3, 'How many resonance structures does the allyl radical have?', '2', ['1', '3', '4'], 'The radical can sit on either terminal carbon.')
    # ------------------------------------------------------------ 10.2 Patterns
    b.mc('10.2', 1, 'A step in which a bond breaks and each atom keeps one electron is called:', 'Homolytic cleavage', ['Heterolytic cleavage', 'Hydride shift', 'Proton transfer'], 'Homolytic cleavage produces two radicals.')
    b.mc('10.2', 1, 'The three stages of a radical chain reaction are:', 'Initiation, propagation and termination', ['Addition, elimination and substitution', 'Protonation, attack and deprotonation', 'Reduction, oxidation and hydrolysis'], 'Every step of a radical mechanism fits one of these.')
    b.mc('10.2', 2, 'Which step type consumes one radical and produces one radical?', 'Propagation', ['Initiation', 'Termination', 'Homolysis of an initiator'], 'The number of radicals stays the same, so the chain continues.')
    b.mc('10.2', 2, 'A step in which two radicals combine to form a stable molecule is:', 'Termination', ['Initiation', 'Propagation', 'Homolysis'], 'Coupling removes two radicals from the reaction.')
    b.mc('10.2', 2, 'A step that creates radicals from a molecule with no radicals present is:', 'Initiation', ['Propagation', 'Termination', 'Chain transfer'], 'Initiation produces the first radicals, often by light or heat.')
    b.mc('10.2', 3, 'Cl• + CH₄ → HCl + CH₃• is which type of radical step?', 'Hydrogen abstraction (propagation)', ['Homolytic cleavage (initiation)', 'Coupling (termination)', 'Addition to a π bond'], 'A hydrogen atom is removed from methane by the chlorine radical.')
    b.mc('10.2', 3, 'CH₃• + Cl₂ → CH₃Cl + Cl• is which type of radical step?', 'Halogen abstraction (propagation)', ['Hydrogen abstraction (propagation)', 'Coupling (termination)', 'Homolytic cleavage (initiation)'], 'The methyl radical takes a chlorine atom from Cl₂.')
    # ------------------------------------------------------------ 10.3 / 10.4 Halogenation of methane
    b.mc('10.3', 1, 'What conditions start the chlorination of methane?', 'Light (hν) or heat', ['A strong base', 'A strong acid', 'A metal catalyst only'], 'Light breaks the Cl-Cl bond homolytically.')
    b.mc('10.3', 2, 'What is the initiation step in the chlorination of methane?', 'Cl-Cl → 2 Cl•', ['CH₄ → CH₃• + H•', 'Cl• + CH₄ → HCl + CH₃•', 'CH₃• + Cl• → CH₃Cl'], 'The weakest bond, Cl-Cl, breaks first.')
    b.mc('10.3', 2, 'Why is the chlorination of methane called a chain reaction?', 'The two propagation steps regenerate the radical that starts the cycle', ['It forms long polymers', 'It needs many catalysts', 'It runs in many solvents'], 'One Cl• can cause many cycles.')
    b.mc('10.3', 3, 'Which compound is formed in a termination step of methane chlorination?', 'Ethane', ['Chloroform', 'Methanol', 'Hydrogen'], 'Two methyl radicals can couple to make ethane.')
    b.mc('10.3', 3, 'What is the net reaction of the two propagation steps of methane chlorination?', 'CH₄ + Cl₂ → CH₃Cl + HCl', ['CH₄ + 2 Cl₂ → CH₂Cl₂ + 2 HCl', 'CH₄ + Cl• → CH₃Cl + H•', '2 CH₄ → C₂H₆ + H₂'], 'Add the two propagation steps; the radicals cancel.', bal=(['C', 'ClCl'], ['CCl', 'Cl']))
    b.mc('10.4', 2, 'Bromination of an alkane is generally ______ chlorination.', 'Slower than', ['Faster than', 'Identical in rate to', 'Not possible, unlike'], 'The hydrogen abstraction step for Br• is endothermic.')
    b.mc('10.4', 3, 'Use C-H 414, Cl-Cl 243, C-Cl 339 and H-Cl 431 kJ/mol. What is ΔH for CH₃• + Cl₂ → CH₃Cl + Cl•?', '−96 kJ/mol', ['+96 kJ/mol', '−17 kJ/mol', '+17 kJ/mol'], 'Bonds broken: 243. Bonds formed: 339. ΔH = 243 − 339.')
    b.mc('10.4', 3, 'Use C-H 414 and H-Cl 431 kJ/mol. What is ΔH for Cl• + CH₄ → HCl + CH₃•?', '−17 kJ/mol', ['+17 kJ/mol', '−845 kJ/mol', '+845 kJ/mol'], 'Bonds broken: 414. Bonds formed: 431. ΔH = 414 − 431.')
    # ------------------------------------------------------------ 10.5 Selectivity
    b.mc('10.5', 1, 'Radical halogenation occurs more readily at which kind of hydrogen?', 'Tertiary C-H', ['Primary C-H', 'Methyl C-H', 'All equally'], 'The more substituted radical is more stable.')
    b.mc('10.5', 2, 'Which halogen is more selective in radical halogenation?', 'Bromine', ['Chlorine', 'They are equally selective', 'Neither'], 'Bromine abstracts hydrogen in an endothermic step with a late transition state.')
    b.mcstruct('10.5', 3, 'What is the major product of isobutane (2-methylpropane) with Br₂, hν?', 'CC(C)(C)Br', ['CC(C)CBr', 'CC(Br)CBr', 'BrC(Br)C(C)C'], 'Bromine is highly selective for the tertiary hydrogen.')
    b.mc('10.5', 3, 'How many different monochlorination products (constitutional isomers) can propane give?', '2', ['1', '3', '4'], '1-Chloropropane and 2-chloropropane.', img=S('CCC'))
    b.mc('10.5', 3, 'How many monochlorination products (constitutional isomers) can 2-methylpropane give?', '2', ['1', '3', '4'], '1-chloro-2-methylpropane and 2-chloro-2-methylpropane.', img=S('CC(C)C'))
    b.mc('10.5', 4, 'In the chlorination of 2-methylbutane, the monochloro product ratio is not simply 9:2:1 because:', 'Tertiary hydrogens are more reactive per hydrogen', ['Primary hydrogens are more reactive', 'Chlorine is very selective', 'All hydrogens are equally reactive'], 'You must weigh the number of hydrogens by their relative reactivity.', img=S('CCC(C)C'))
    # ------------------------------------------------------------ 10.6 Stereochemistry
    b.mc('10.6', 2, 'Radical bromination creates a new chirality center in a molecule. What is the stereochemical outcome?', 'Both stereoisomers form in equal amounts', ['Only one enantiomer', 'Inversion only', 'Retention only'], 'The radical carbon is planar, so the halogen adds to either face.')
    b.mc('10.6', 3, '(R)-3-Methylhexane undergoes radical bromination at C3. What is the product?', 'A racemic mixture of 3-bromo-3-methylhexane', ['(R)-3-Bromo-3-methylhexane only', '(S)-3-Bromo-3-methylhexane only', 'No reaction'], 'The planar radical intermediate loses stereochemical information.', img=S('CCC[C@@H](C)CC'))
    b.mc('10.6', 4, 'Why does halogenation at a chirality center give a racemic mixture?', 'The intermediate radical is planar and is attacked equally from both faces', ['The reaction proceeds by SN2 inversion', 'The halogen adds only from one side', 'The chirality center is destroyed in a carbocation'], 'A trigonal planar radical has no preferred face.')
    # ------------------------------------------------------------ 10.7 Allylic bromination
    b.mc('10.7', 1, 'Which reagent is used for allylic bromination?', 'NBS', ['HBr', 'Br₂ in the dark', 'NaBr'], 'N-bromosuccinimide provides a low concentration of Br₂.')
    b.mcstruct('10.7', 2, 'What is the major product of cyclohexene with NBS, hν?', 'BrC1C=CCCC1', ['BrC1CCCCC1Br', 'BrC1CCCCC1', 'BrC1=CCCCC1'], 'Bromination occurs at the allylic position.')
    b.mc('10.7', 2, 'Why is NBS used instead of Br₂ for allylic bromination of an alkene?', 'To keep Br₂ concentration low and avoid ionic addition to the double bond', ['To speed up the ionic addition', 'To make the alkene more reactive', 'To make HBr'], 'Low Br₂ concentration prevents the competing addition.')
    b.mc('10.7', 3, 'Which hydrogen of 1-butene is removed in allylic bromination?', 'A hydrogen on C3', ['A hydrogen on C1', 'A hydrogen on C2', 'A hydrogen on C4'], 'The allylic position is the carbon next to the double bond.', img=S('C=CCC'))
    b.mc('10.7', 3, 'Why does allylic bromination of an unsymmetrical alkene often give two products?', 'The allylic radical has two resonance structures', ['Two initiation steps occur', 'The ring opens', 'Bromine adds twice'], 'Br can attach to either end of the allylic radical.')
    # ------------------------------------------------------------ 10.8 - 10.9
    b.mc('10.8', 1, 'Which compounds were responsible for depleting stratospheric ozone?', 'CFCs (chlorofluorocarbons)', ['HFCs', 'Alkanes', 'Alkenes'], 'CFCs release chlorine radicals in the stratosphere.')
    b.mc('10.8', 2, 'What replaced CFCs as refrigerants?', 'Hydrofluorocarbons (HFCs)', ['Freons', 'Chloroform', 'Carbon tetrachloride'], 'HFCs contain no chlorine.')
    b.mc('10.9', 1, 'What is autooxidation?', 'Reaction of an organic compound with atmospheric oxygen via radicals to give hydroperoxides', ['Reaction with a strong acid', 'Reaction with water', 'A reduction by hydrogen'], 'Autooxidation is a radical chain process.')
    b.mc('10.9', 2, 'What does an antioxidant such as BHT do?', 'Traps radicals and stops the chain reaction', ['Creates radicals', 'Adds oxygen to alkenes', 'Catalyses polymerisation'], 'It is a radical scavenger.')
    b.mc('10.9', 2, 'Which is a natural antioxidant?', 'Vitamin E', ['Freon', 'Peroxide', 'Chloroform'], 'Vitamins E and C are natural antioxidants.')
    b.mc('10.9', 3, 'Which compound is a radical initiator?', 'A peroxide (such as ROOR)', ['Hydroquinone', 'BHT', 'O₂'], 'Its weak O-O bond breaks homolytically.')
    # ------------------------------------------------------------ 10.10 / 10.11 Addition and polymers
    b.mcstruct('10.10', 2, 'What is the major product of 1-butene with HBr in the presence of peroxides?', 'CCCCBr', ['CCC(C)Br', 'CC(Br)C(C)Br', 'CCCC'], 'Anti-Markovnikov addition through the more stable secondary radical.')
    b.mc('10.10', 3, 'In radical addition of HBr to propene, which radical does Br• create?', 'A secondary radical (Br adds to the terminal carbon)', ['A primary radical (Br adds to C2)', 'A carbocation', 'A carbanion'], 'The Br atom adds so that the more stable radical forms.', img=S('C=CC'))
    b.mc('10.10', 3, 'HCl adds to alkenes with peroxides in an anti-Markovnikov sense.', 'False: only HBr works well in the radical chain', ['True', 'True, only for tertiary alkenes', 'True, only for rings'], 'The propagation steps are only favorable for HBr.')
    b.mc('10.11', 1, 'What is the repeating unit of polyethylene made from?', 'Ethylene (ethene)', ['Propylene', 'Styrene', 'Vinyl chloride'], 'Polyethylene is made by polymerisation of ethene.')
    b.mc('10.11', 2, 'PVC is made by polymerizing:', 'Vinyl chloride', ['Chloroethane', 'Ethylene', 'Chlorobenzene'], 'Vinyl chloride is CH₂=CHCl.', img=S('C=CCl'))
    b.mc('10.11', 3, 'Which type of step grows the polymer chain in radical polymerisation?', 'Addition of a radical to a π bond', ['Hydrogen abstraction', 'Termination', 'Homolysis of an initiator'], 'Each propagation step adds one more monomer.')
    b.mc('10.12', 2, 'What is cracking in the petrochemical industry?', 'Breaking large hydrocarbons into smaller ones', ['Joining small molecules', 'Adding oxygen', 'Removing hydrogen from rings'], 'Cracking breaks C-C bonds by radical processes at high temperature.')
    b.mc('10.13', 3, 'To convert 2-methylbutane into 2-methylbut-2-ene, a good route is:', '(1) Br₂, hν; (2) NaOEt, heat', ['(1) NBS; (2) H₂O', '(1) HBr; (2) Mg', '(1) H₂, Pt; (2) Br₂'], 'Selective radical bromination, then E2 elimination.', img=S('CCC(C)C'))
    b.mc('10.13', 4, 'To convert propane into propene, which two steps are best?', '(1) Br₂, hν; (2) NaOEt, heat', ['(1) Cl₂, hν; (2) NaOH, cold', '(1) NBS; (2) H₂O', '(1) HBr; (2) KOH'], 'Brominate (mostly at C2), then eliminate with a strong base.', img=S('CCC'))

    # ================================================================ free response
    b.fr('10.1', 1, 'What is a radical, and what arrow shows its reactions?', 'A radical has an unpaired electron; its reactions are drawn with fishhook (single-headed) arrows.', 'One electron per arrow.')
    b.fr('10.1', 2, 'Rank the radicals methyl, primary, secondary and tertiary by stability.', 'Tertiary > secondary > primary > methyl.', 'More alkyl groups stabilise the radical.')
    b.fr('10.1', 2, 'Explain why the allyl radical is more stable than a primary alkyl radical.', 'The unpaired electron is delocalised over two carbons through resonance.', 'Draw both resonance structures.', img=S('C=C[CH2]', radical=True))
    b.fr('10.1', 3, 'Draw the two resonance structures of the allyl radical.', 'CH₂=CH-CH₂• ↔ •CH₂-CH=CH₂; the radical is shared by the two terminal carbons.', 'Move one electron with fishhook arrows.', aimg=S('C=C[CH2]', '[CH2]C=C', radical=True))
    b.fr('10.1', 3, 'Why is a vinylic radical not stabilised by resonance?', 'The unpaired electron is in an sp² orbital in the plane of the molecule, perpendicular to the π system, so it cannot overlap with the π bond.', 'Consider orbital alignment.')
    b.fr('10.2', 1, 'Name the three stages of a radical chain mechanism.', 'Initiation, propagation and termination.', 'Start, continue, end.')
    b.fr('10.2', 2, 'List the six kinds of radical steps.', 'Homolytic cleavage, addition to a π bond, hydrogen abstraction, halogen abstraction, elimination and coupling.', 'Klein section 10.2.')
    b.fr('10.2', 2, 'Classify Cl• + CH₄ → HCl + CH₃• as initiation, propagation or termination, and as a step type.', 'Propagation; hydrogen abstraction.', 'One radical consumed, one produced.')
    b.fr('10.2', 3, 'Explain why a termination step ends the chain.', 'Two radicals combine into a stable molecule, so no radical is left to continue the cycle.', 'Radicals are consumed.')
    b.fr('10.3', 2, 'Write the initiation step of the chlorination of methane.', 'Cl-Cl → 2 Cl• (homolytic cleavage by light or heat).', 'Weakest bond.')
    b.fr('10.3', 2, 'Write both propagation steps of the chlorination of methane.', 'Cl• + CH₄ → HCl + CH₃•; CH₃• + Cl₂ → CH₃Cl + Cl•.', 'Hydrogen abstraction then halogen abstraction.')
    b.fr('10.3', 3, 'Show that the two propagation steps add up to the net reaction.', 'Cl• + CH₄ + CH₃• + Cl₂ → HCl + CH₃• + CH₃Cl + Cl•; cancelling Cl• and CH₃• leaves CH₄ + Cl₂ → CH₃Cl + HCl.', 'Add and cancel the radicals.')
    b.fr('10.3', 3, 'Give three possible termination steps in the chlorination of methane.', 'Cl• + Cl• → Cl₂; CH₃• + Cl• → CH₃Cl; CH₃• + CH₃• → CH₃CH₃.', 'Two radicals combine.')
    b.fr('10.3', 3, 'Why is a small amount of light enough to convert a large amount of methane to chloromethane?', 'The propagation steps form a chain reaction in which each chlorine radical regenerates itself and can cause many cycles.', 'Chain reaction.')
    b.fr('10.4', 3, 'Use C-H 414, Cl-Cl 243, C-Cl 339 and H-Cl 431 kJ/mol to calculate ΔH for each propagation step of methane chlorination.', 'Step 1: 414 − 431 = −17 kJ/mol. Step 2: 243 − 339 = −96 kJ/mol. Overall −113 kJ/mol.', 'Bonds broken minus bonds formed.', bal=(['C', 'ClCl'], ['CCl', 'Cl']))
    b.fr('10.4', 2, 'Which is more practical in the laboratory: radical chlorination or radical iodination? Explain briefly.', 'Chlorination, since the iodination propagation step is too unfavorable (only chlorination and bromination are practical).', 'Only Cl and Br are useful.')
    b.fr('10.5', 2, 'Explain why radical halogenation occurs more readily at tertiary hydrogens.', 'Abstracting a tertiary hydrogen forms the most stable (tertiary) radical, with the lowest energy transition state.', 'Radical stability.')
    b.fr('10.5', 2, 'Which is more selective, bromination or chlorination, and why?', 'Bromination; its hydrogen abstraction step is endothermic with a late transition state, which resembles the radical and magnifies stability differences.', 'Late transition state.')
    b.fr('10.5', 3, 'Draw the major product of isobutane with Br₂, hν and explain.', '2-Bromo-2-methylpropane; bromine is highly selective for the tertiary hydrogen.', 'Selectivity of Br•.', img=S('CC(C)C'), aimg=S('CC(C)(C)Br'))
    b.fr('10.5', 3, 'Draw all monochlorination products of propane.', '1-Chloropropane and 2-chloropropane.', 'Two types of hydrogen.', img=S('CCC'), aimg=S('CCCCl', 'CC(C)Cl'))
    b.fr('10.5', 4, 'Chlorination of 2-methylbutane gives four monochloro constitutional isomers. Draw them.', '1-Chloro-2-methylbutane, 2-chloro-2-methylbutane, 2-chloro-3-methylbutane and 1-chloro-3-methylbutane.', 'Count the types of hydrogens.', img=S('CCC(C)C'), aimg=S('CCC(C)CCl', 'CCC(C)(C)Cl', 'CC(Cl)C(C)C', 'CC(C)CCCl') if False else S('CCC(C)CCl', 'CCC(C)(C)Cl', 'CC(Cl)C(C)C', 'CC(C)CCl'))
    b.fr('10.6', 2, 'Radical bromination of butane at C2 creates a chirality center. What is the stereochemical result?', 'A racemic mixture of (R)- and (S)-2-bromobutane, because the radical is planar and Br₂ attacks either face.', 'Planar radical.', img=S('CCCC'), aimg=S('C[C@H](Br)CC', 'C[C@@H](Br)CC'))
    b.fr('10.6', 3, 'Explain why bromination of optically pure (R)-3-methylhexane at C3 gives an optically inactive product.', 'The radical at C3 is planar and achiral, and Br₂ attacks either face equally, giving a racemic mixture.', 'Radical intermediate.', img=S('CCC[C@@H](C)CC'))
    b.fr('10.6', 3, 'Why does the chirality of a starting material not control the outcome of a radical substitution at that center?', 'Because the intermediate radical is planar, so the original configuration is lost.', 'Planar radical.')
    b.fr('10.7', 1, 'What reagent is used for allylic bromination?', 'N-Bromosuccinimide (NBS) with light or a radical initiator.', 'NBS.')
    b.fr('10.7', 2, 'Draw the product of cyclohexene with NBS, hν.', '3-Bromocyclohexene.', 'Allylic position.', img=S('C1=CCCCC1'), aimg=S('BrC1C=CCCC1'))
    b.fr('10.7', 2, 'Draw the product of propene with NBS, hν.', '3-Bromopropene (allyl bromide).', 'Allylic bromination.', img=S('C=CC'), aimg=S('C=CCBr'))
    b.fr('10.7', 3, 'Why does Br₂ at high concentration add to alkenes but NBS gives allylic substitution?', 'NBS keeps the concentration of Br₂ very low, so the ionic addition via a bromonium ion is slow compared with the radical chain substitution.', 'Concentration of Br₂.')
    b.fr('10.7', 3, 'Explain why allylic bromination of 1-butene can give two products.', 'The allylic radical is resonance-stabilised, so Br₂ can attack either end, giving 3-bromobut-1-ene and 1-bromobut-2-ene.', 'Two resonance structures.', img=S('C=CCC'), aimg=S('C=CC(C)Br', 'CC=CCBr'))
    b.fr('10.7', 4, 'Outline the mechanism of allylic bromination of cyclohexene with NBS: name the two propagation steps.', 'Br• abstracts an allylic hydrogen to give a resonance-stabilised allylic radical and HBr; the radical abstracts a Br from Br₂ to give 3-bromocyclohexene and Br•.', 'Hydrogen abstraction then halogen abstraction.')
    b.fr('10.8', 1, 'What are CFCs, and what problem did they cause?', 'Chlorofluorocarbons; they release chlorine radicals in the stratosphere that destroy the ozone layer.', 'Ozone depletion.')
    b.fr('10.8', 2, 'Why were HFCs introduced as replacements for CFCs?', 'HFCs contain no chlorine, so they do not generate chlorine radicals that destroy ozone.', 'No chlorine.')
    b.fr('10.9', 1, 'What is autooxidation?', 'A radical chain reaction of organic compounds with atmospheric oxygen that forms hydroperoxides.', 'Spontaneous oxidation by O₂.')
    b.fr('10.9', 2, 'Explain how BHT preserves foods.', 'BHT is a radical scavenger: it donates a hydrogen atom to peroxy radicals, forming a stable radical that does not continue the chain.', 'Radical trap.')
    b.fr('10.9', 3, 'Name two natural antioxidants.', 'Vitamin E and vitamin C.', 'Protect cell membranes.')
    b.fr('10.10', 1, 'What conditions cause HBr to add to an alkene in an anti-Markovnikov sense?', 'HBr with peroxides (ROOR) or light.', 'Radical mechanism.')
    b.fr('10.10', 2, 'Draw the product of propene with HBr in the presence of peroxides.', '1-Bromopropane.', 'Anti-Markovnikov.', img=S('C=CC'), aimg=S('CCCBr'))
    b.fr('10.10', 3, 'Explain the regiochemistry of radical addition of HBr to propene.', 'Br• adds to the terminal carbon, forming the more stable secondary radical; this radical then abstracts H from HBr, giving 1-bromopropane.', 'More stable radical.', img=S('C=CC'))
    b.fr('10.10', 3, 'Why does radical addition work for HBr but not for HCl or HI?', 'For HCl the hydrogen abstraction step is too endothermic; for HI the addition of I• to the alkene is too unfavorable.', 'One of the propagation steps is unfavorable.')
    b.fr('10.11', 1, 'What monomer gives polyvinyl chloride (PVC)?', 'Vinyl chloride (chloroethene).', 'CH₂=CHCl.', img=S('C=CCl'))
    b.fr('10.11', 2, 'Explain why polymerisation of ethylene through a radical process gives chain branching.', 'A growing chain radical can abstract a hydrogen from within its own chain (backbiting), creating a new radical site from which a branch grows.', 'Hydrogen abstraction.')
    b.fr('10.11', 3, 'Draw the repeating unit of polyvinyl chloride and the monomer it comes from.', 'Monomer CH₂=CHCl; repeating unit -CH₂-CHCl-.', 'The π bond opens.', aimg=S('C=CCl', 'CC(Cl)C(Cl)') if False else S('C=CCl'))
    b.fr('10.12', 2, 'What is cracking?', 'Breaking larger hydrocarbons into smaller ones, such as gasoline-range alkanes and alkenes, at high temperature.', 'Radical process.')
    b.fr('10.13', 3, 'Propose a synthesis of 2-methylbut-2-ene from 2-methylbutane.', '(1) Br₂, hν (selective at the tertiary C-H) to give 2-bromo-2-methylbutane; (2) NaOEt, heat (E2).', 'Brominate, then eliminate.', img=S('CCC(C)C'), aimg=S('CC=C(C)C'))
    b.fr('10.13', 3, 'Propose a synthesis of 3-bromocyclohexene... from cyclohexane in two steps.', '(1) Br₂, hν to give bromocyclohexane; (2) NaOEt, heat to give cyclohexene; then NBS, hν.', 'Halogenate, eliminate, then allylic bromination.') if False else None
    b.fr('10.13', 4, 'Propose a synthesis of trans-cyclohexane-1,2-diol from cyclohexane.', '(1) Br₂, hν; (2) NaOEt, heat to give cyclohexene; (3) mCPBA; (4) H₃O⁺.', 'Radical bromination, elimination, anti dihydroxylation.', img=S('C1CCCCC1'), aimg=S('O[C@@H]1CCCC[C@H]1O'))
    b.fr('10.13', 4, 'Propose a synthesis of 1-bromopropane from propane.', '(1) Br₂, hν gives mostly 2-bromopropane; (2) NaOEt, heat gives propene; (3) HBr, ROOR gives 1-bromopropane.', 'Anti-Markovnikov radical addition.', img=S('CCC'), aimg=S('CCCBr'))
    b.fr('10.13', 3, 'Why is radical bromination preferred over chlorination when a single product is wanted?', 'Bromine is much more selective, so it reacts mostly at the most substituted (tertiary) C-H and gives one major product.', 'Selectivity.')
    b.fr('10.1', 2, 'Which is more stable, a secondary radical or a primary radical? Give the reason.', 'The secondary radical; its extra alkyl group stabilises the unpaired electron by hyperconjugation, the same trend seen for carbocations.', 'More alkyl groups, more stable.')
    b.fr('10.3', 1, 'What does hν mean in a reaction scheme?', 'Light (a photon of energy hν) used to start the reaction, here by breaking a weak bond homolytically.', 'Light as the initiator.')
    b.fr('10.9', 2, 'What is a radical inhibitor? Give one example.', 'A compound that stops a radical chain by reacting with radicals to form stable products; examples include oxygen and hydroquinone.', 'Radical scavenger.')
